    const type = mime(doc), canPrintOriginal = type === 'application/pdf' || type.startsWith('image/') || type === 'text/plain';
    const popup = window.open(canPrintOriginal ? `/api/documents/${encodeURIComponent(id)}/preview` : 'about:blank', '_blank');
