    const meta = `<header><small>FOLIO VAULT · PRINT VIEW</small><h1>${escape(doc.name || doc.original_name)}</h1><div class="meta">${escape(doc.original_name || '')}</div></header><p><b>Category:</b> ${escape(doc.category || 'Uncategorized')} &nbsp; <b>Type:</b> ${escape(type || 'Unknown')} &nbsp; <b>Size:</b> ${prettySize(doc.file_size)}</p><p>This print view contains file information. Download the original to print the complete contents in its native application.</p>`;
    if (type !== 'text/csv') { printPage(doc.name || doc.original_name, meta); return; }
